341	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
342	func (s *Store) persist(st *persistedState) error {
343		data, err := json.MarshalIndent(st, "", "  ")
344		if err != nil {
345			return err
346		}
347		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
348		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
349		if err != nil {
350			return err
351		}
352		if _, err := f.Write(data); err != nil {
353			f.Close()
354			return err
355		}
356		if err := f.Sync(); err != nil {
357			f.Close()
358			return err
359		}
360		if err := f.Close(); err != nil {
361			return err
362		}
363		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
364			return err
365		}
366		if d, err := os.Open(s.dir); err == nil {
367			_ = d.Sync()
368			_ = d.Close()
369		}
370		return nil
371	}
