373	func cloneState(st *persistedState) (*persistedState, error) {
374		data, err := json.Marshal(st)
375		if err != nil {
376			return nil, err
377		}
378		var out persistedState
379		if err := json.Unmarshal(data, &out); err != nil {
380			return nil, err
381		}
382		if out.Requests == nil {
383			out.Requests = map[string]*requestRecord{}
384		}
385		return &out, nil
386	}
387	
388	// write 是所有写入操作的统一入口：
389	//   - reqNo 为空直接报错；
390	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
391	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
392	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
393	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
394	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
395		if reqNo == "" {
396			return errors.New("请求编号不能为空")
397		}
398		s.mu.Lock()
399		defer s.mu.Unlock()
400		if err := s.lockExclusive(); err != nil {
401			return err
402		}
403		defer s.unlock()
404	
405		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
406		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
407		if err := s.load(); err != nil {
408			return err
409		}
410	
411		payloadRaw, err := json.Marshal(payload)
412		if err != nil {
413			return err
414		}
415		payloadStr := string(payloadRaw)
416	
417		if req, ok := s.state.Requests[reqNo]; ok {
418			if req.Op != op || req.Payload != payloadStr {
419				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
420					ErrRequestConflict, reqNo, req.Op, op)
421			}
422			if err := json.Unmarshal(req.Result, out); err != nil {
423				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
424			}
425			return nil
426		}
427	
428		clone, err := cloneState(s.state)
429		if err != nil {
430			return err
431		}
432		result, err := apply(clone)
433		if err != nil {
434			return err
435		}
436		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
437		if err := s.persist(clone); err != nil {
438			return fmt.Errorf("保存台账失败: %w", err)
439		}
440		s.state = clone
441		if err := json.Unmarshal(result, out); err != nil {
442			return fmt.Errorf("解析请求结果失败: %w", err)
443		}
444		return nil
445	}
446	
447	// read 在共享锁下读取当前状态。
448	func (s *Store) read(fn func(*persistedState) error) error {
449		s.mu.Lock()
450		defer s.mu.Unlock()
451		if err := s.lockShared(); err != nil {
452			return err
453		}
454		defer s.unlock()
455		if err := s.load(); err != nil {
456			return err
457		}
458		return fn(s.state)
459	}
