461	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
462	
463	func buildRecipeView(r *recipeRecord) *RecipeView {
464		mats := make([]MaterialView, 0, len(r.Materials))
465		for _, m := range r.Materials {
466			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
467		}
468		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
469	}
470	
471	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
472		v := &BatchView{
473			BatchNo:         b.BatchNo,
474			RecipeNo:        r.RecipeNo,
475			RecipeVersion:   r.Version,
476			RecipeName:      r.Name,
477			PlannedPortions: b.PlannedPortions,
478			Status:          b.Status,
479			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
480			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
481		}
482	
483		for _, f := range b.Feedings {
484			v.Feedings = append(v.Feedings, FeedingView{
485				Seq:        f.Seq,
486				MaterialNo: f.MaterialNo,
487				Grams:      f.GramsMilli.String(),
488				Time:       f.Time,
489				Registrar:  f.Registrar,
490			})
491		}
492	
493		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
494		// 这里仍用同一套累计规则防一手整数回绕。
495		acc := newFeedingAccumulator()
496		for _, f := range b.Feedings {
497			if !acc.add(f.MaterialNo, f.GramsMilli) {
498				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
499					ErrCorruptData, b.BatchNo, f.MaterialNo)
500			}
501		}
502	
503		// 数量核对按配方物料逐项列出；应投量统一由 planRequirements 按本批次
504		// 绑定版本与计划份数计算，与创建、调整、读取校验共用同一套规则。
505		// 台账在读取时已通过 validateState 校验，这里仍防一手同一版本内物料
506		// 编号重复，避免返回重复的数量核对项。
507		required, err := planRequirements(r, b.PlannedPortions)
508		if err != nil {
509			return nil, fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
510		}
511		seen := make(map[string]bool, len(required))
512		for _, item := range required {
513			if seen[item.materialNo] {
514				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
515					ErrCorruptData, r.RecipeNo, r.Version, item.materialNo)
516			}
517			seen[item.materialNo] = true
518			act := acc.total(item.materialNo)
519			v.Materials = append(v.Materials, MaterialRequirement{
520				MaterialNo:      item.materialNo,
521				RequiredGrams:   item.requiredGrams.String(),
522				ActualGrams:     act.String(),
523				DifferenceGrams: (act - item.requiredGrams).String(),
524			})
525		}
526		return v, nil
527	}
