36	func checkRequirement(t *testing.T, got map[string]MaterialRequirement, mat, req, act, diff string) {
37		t.Helper()
38		m, ok := got[mat]
39		if !ok {
40			t.Fatalf("数量核对缺少物料 %q，实际有 %+v", mat, got)
41		}
42		if m.RequiredGrams != req || m.ActualGrams != act || m.DifferenceGrams != diff {
43			t.Fatalf("物料 %q 核对应为 应投=%s 实投=%s 差额=%s，得到 应投=%s 实投=%s 差额=%s",
44				mat, req, act, diff, m.RequiredGrams, m.ActualGrams, m.DifferenceGrams)
45		}
46	}
