1	package release
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"os/exec"
8		"path/filepath"
9		"strings"
10		"sync"
11		"testing"
12		"time"
13	)
14	
15	func openTestStore(t *testing.T) *Store {
16		t.Helper()
17		dir := t.TempDir()
18		s, err := Open(dir)
19		if err != nil {
20			t.Fatalf("Open(%q) 失败: %v", dir, err)
21		}
22		t.Cleanup(func() { s.Close() })
23		return s
24	}
25	
26	func registerStandardRecipe(t *testing.T, s *Store, reqNo string) {
27		t.Helper()
28		_, err := s.RegisterRecipe(reqNo, "R1", "v1", "标准配方", []MaterialInput{
29			{MaterialNo: "M1", Grams: "100"},
30			{MaterialNo: "M2", Grams: "0.5"},
31			{MaterialNo: "M3", Grams: "0.010"},
32		})
33		if err != nil {
34			t.Fatalf("登记配方失败: %v", err)
35		}
36	}
37	
38	// 首次使用空位置：台账为空，查询返回未找到。
39	func TestOpenEmptyAndNotFound(t *testing.T) {
40		s := openTestStore(t)
41		if _, err := s.GetBatch("B1"); !errors.Is(err, ErrNotFound) {
42			t.Fatalf("查询不存在的批次应返回 ErrNotFound，得到 %v", err)
43		}
44		if _, err := s.GetRecipe("R1", "v1"); !errors.Is(err, ErrNotFound) {
45			t.Fatalf("查询不存在的配方应返回 ErrNotFound，得到 %v", err)
46		}
47	}
48	
49	// 空位置关闭后重新打开，仍然为空台账。
50	func TestReopenEmptyLocation(t *testing.T) {
51		dir := t.TempDir()
52		s1, err := Open(dir)
53		if err != nil {
54			t.Fatal(err)
55		}
56		if err := s1.Close(); err != nil {
57			t.Fatal(err)
58		}
59		s2, err := Open(dir)
60		if err != nil {
61			t.Fatal(err)
62		}
63		defer s2.Close()
64		if _, err := s2.GetBatch("B1"); !errors.Is(err, ErrNotFound) {
65			t.Fatalf("重新打开空位置应得到空台账，得到 %v", err)
66		}
67	}
68	
69	func TestRegisterRecipeAndGet(t *testing.T) {
70		s := openTestStore(t)
71		view, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
72			{MaterialNo: "M1", Grams: "100"},
73			{MaterialNo: "M2", Grams: "0.500"},
74		})
75		if err != nil {
76			t.Fatalf("登记配方失败: %v", err)
77		}
78		if view.RecipeNo != "R1" || view.Version != "v1" || view.Name != "配方一" {
79			t.Fatalf("配方视图不正确: %+v", view)
80		}
81		if len(view.Materials) != 2 || view.Materials[0].Grams != "100" || view.Materials[1].Grams != "0.5" {
82			t.Fatalf("物料视图不正确: %+v", view.Materials)
83		}
84	
85		got, err := s.GetRecipe("R1", "v1")
86		if err != nil {
87			t.Fatalf("查询配方失败: %v", err)
88		}
89		if got.Name != "配方一" || len(got.Materials) != 2 {
